/**
 * Computes the output path of the incremental compilation state file
 * (.tsbuildinfo) for a given tsconfig. The path is always a specific file (not
 * a glob) so that a cache restore reliably brings back the state file and
 * incremental compilation keeps working after a cache hit.
 *
 * Precedence follows how `tsc` resolves the location:
 * - an explicit `tsBuildInfoFile` wins,
 * - otherwise, when `outFile` is set, it sits next to the `outFile`,
 * - otherwise, when `outDir` is set, it's placed in the `outDir`,
 * - otherwise, it's emitted in place at the project root.
 *
 * The file name defaults to the tsconfig base name (without extension), e.g.
 * `tsconfig.json` -> `tsconfig.tsbuildinfo`.
 */
function getTsBuildInfoOutput(
  config: ConfigContext,
  tsConfig: ParsedTsconfigData,
  configBaseNameNoExt: string,
  workspaceRoot: string
): string {
  if (tsConfig.options.tsBuildInfoFile) {
    return pathToInputOrOutput(
      tsConfig.options.tsBuildInfoFile,
      workspaceRoot,
      config.project
    );
  }

  if (tsConfig.options.outFile) {
    const outFileName = basename(tsConfig.options.outFile, '.js');
    const outDir = relative(workspaceRoot, dirname(tsConfig.options.outFile));
    return pathToInputOrOutput(
      joinPathFragments(outDir, `${outFileName}.tsbuildinfo`),
      workspaceRoot,
      config.project
    );
  }

  if (tsConfig.options.outDir) {
    return pathToInputOrOutput(
      joinPathFragments(
        tsConfig.options.outDir,
        `${configBaseNameNoExt}.tsbuildinfo`
      ),
      workspaceRoot,
      config.project
    );
  }

  return joinPathFragments(
    '{projectRoot}',
    `${configBaseNameNoExt}.tsbuildinfo`
  );
}

